@Composable fun RegisterScreen( viewModel: AuthViewModel, onNavigateToLogin: () -> Unit ) { val state by viewModel.state.collectAsStateWithLifecycle() val event by viewModel.event.collectAsStateWithLifecycle()
LaunchedEffect(event) { if (event == AuthEvent.Registered) { viewModel.clearEvent() onNavigateToLogin() } }
Column( modifier = Modifier .fillMaxSize() .padding(24.dp), verticalArrangement = Arrangement.Center ) { Text(text = "Create account", style = MaterialTheme.typography.headlineMedium) Spacer(modifier = Modifier.height(16.dp))
