OutlinedTextField( value = state.password, onValueChange = viewModel::onPasswordChanged, label = { Text("Password") }, singleLine = true, modifier = Modifier.fillMaxSize(), colors = TextFieldDefaults.outlinedTextFieldColors() ) Spacer(modifier = Modifier.height(12.dp))
OutlinedTextField( value = state.confirmPassword, onValueChange = viewModel::onConfirmPasswordChanged, label = { Text("Confirm Password") }, singleLine = true, modifier = Modifier.fillMaxSize(), colors = TextFieldDefaults.outlinedTextFieldColors() ) Spacer(modifier = Modifier.height(12.dp))
RoleToggle(selected = state.selectedRole, onRoleSelected = viewModel::onRoleSelected)
state.errorMessage?.let { Spacer(modifier = Modifier.height(8.dp)) Text(text = it, color = MaterialTheme.colorScheme.error) }
Spacer(modifier = Modifier.height(16.dp)) Button(onClick = viewModel::register, enabled = !state.isLoading) { Text(text = if (state.isLoading) "Registering..." else "Register") } Spacer(modifier = Modifier.height(8.dp)) TextButton(onClick = onNavigateToLogin) { Text(text = "Go to Login") } } }

